import itertools

def get_king_independent_sets(n):
    cells = list(itertools.product(range(n), range(n)))
    independent_sets = []
    for r in range(2, n*n + 1):
        for subset in itertools.combinations(cells, r):
            is_independent = True
            for p1, p2 in itertools.combinations(subset, 2):
                if max(abs(p1[0]-p2[0]), abs(p1[1]-p2[1])) <= 1:
                    is_independent = False
                    break
            if is_independent:
                independent_sets.append(set(subset))
    return independent_sets

def solve_min_q(n):
    s_sets = get_king_independent_sets(n)
    cells = list(itertools.product(range(n), range(n)))

    for q_size in range(1, n*n + 1):
        for q in itertools.combinations(cells, q_size):
            q_set = set(q)
            seen = set()
            possible = True
            for s in s_sets:
                intersection = tuple(sorted(list(s.intersection(q_set))))
                if intersection in seen:
                    possible = False
                    break
                seen.add(intersection)
            if possible:
                return q_size
    return n*n

for n in range(2, 5):
    print(f"n={n}, min_q={solve_min_q(n)}")

